demo.css:
#demo {
  background: var(--demo-bg);
  color: var(--demo-fg);
  font-family: var(--demo-font, system-ui, -apple-system, sans-serif);
  padding: 16px;
  box-sizing: border-box;
}

#demo * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.palette-demo {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 800px;
  margin: 0 auto;
}

.demo-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.demo-badge {
  display: inline-block;
  align-self: flex-start;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: 4px;
  background: var(--demo-accent);
  color: #fff;
}

.demo-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--demo-fg);
}

.demo-subtitle {
  font-size: 13px;
  color: var(--demo-muted);
}

.samples-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.samples-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--demo-muted);
}

.samples-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.sample-chip {
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  color: var(--demo-fg);
  font-size: 11px;
  padding: 4px 10px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.sample-chip:hover {
  border-color: var(--demo-accent);
  color: var(--demo-accent);
}

.input-card {
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--demo-fg);
}

.input-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.atmos-textarea {
  flex: 1 1 220px;
  background: var(--demo-bg);
  color: var(--demo-fg);
  border: 1px solid var(--demo-border);
  border-radius: 6px;
  padding: 8px 10px;
  font-size: 13px;
  font-family: inherit;
  resize: vertical;
  outline: none;
  transition: border-color 0.2s ease;
}

.atmos-textarea:focus {
  border-color: var(--demo-accent);
}

.analyze-button {
  background: var(--demo-accent);
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: opacity 0.2s ease, transform 0.1s ease;
  align-self: flex-start;
}

.analyze-button:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.analyze-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.status-box {
  font-size: 12px;
  padding: 8px 12px;
  border-radius: 6px;
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  color: var(--demo-muted);
  transition: all 0.2s ease;
}

.status-box.error {
  border-color: #e53e3e;
  color: #e53e3e;
  background: rgba(229, 62, 62, 0.08);
}

.status-box.loading {
  border-color: var(--demo-accent);
  color: var(--demo-accent);
}

.visual-stage {
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: relative;
  overflow: hidden;
}

.celestial-sky {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: var(--demo-bg);
  border: 1px solid var(--demo-border);
  border-radius: 8px;
  transition: background 0.5s ease;
}

.celestial-orb-container {
  width: 36px;
  height: 36px;
  position: relative;
  overflow: hidden;
  border-radius: 50%;
  background: var(--demo-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--demo-border);
}

.celestial-orb {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: absolute;
  top: 6px;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  gap: 14px;
}

.orb-icon {
  font-size: 18px;
  line-height: 1;
}

.sky-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sky-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.sky-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--demo-fg);
}

.sky-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--demo-muted);
}

.sky-meter {
  height: 6px;
  background: var(--demo-surface);
  border-radius: 3px;
  overflow: hidden;
  position: relative;
  border: 1px solid var(--demo-border);
}

.sky-bar-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #f6d365 0%, #fda085 50%, #4a00e0 100%);
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.vats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

@media (max-width: 580px) {
  .vats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 360px) {
  .vats-grid {
    grid-template-columns: 1fr;
  }
}

.vat-card {
  background: var(--demo-bg);
  border: 1px solid var(--demo-border);
  border-radius: 8px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.vat-card.active-archetype {
  border-color: var(--demo-accent);
  box-shadow: 0 0 10px rgba(0,0,0,0.15);
}

.vat-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.vat-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.neon-dot { background: #00f2fe; box-shadow: 0 0 6px #00f2fe; }
.earthy-dot { background: #6b8e23; box-shadow: 0 0 6px #6b8e23; }
.pastel-dot { background: #ffb6c1; box-shadow: 0 0 6px #ffb6c1; }
.sunset-dot { background: #ff7e5f; box-shadow: 0 0 6px #ff7e5f; }

.vat-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--demo-fg);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.vat-container {
  height: 120px;
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  border-radius: 6px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.vat-liquid {
  width: 100%;
  height: 0%;
  transition: height 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  position: absolute;
  bottom: 0;
  left: 0;
  opacity: 0.85;
}

.neon-liquid {
  background: linear-gradient(180deg, #4facfe 0%, #00f2fe 50%, #6b11ff 100%);
}
.earthy-liquid {
  background: linear-gradient(180deg, #a8e063 0%, #56ab2f 50%, #4b3621 100%);
}
.pastel-liquid {
  background: linear-gradient(180deg, #fad0c4 0%, #ffd1ff 50%, #a1c4fd 100%);
}
.sunset-liquid {
  background: linear-gradient(180deg, #feb47b 0%, #ff7e5f 50%, #7b1fa2 100%);
}

.vat-pct {
  position: relative;
  z-index: 2;
  font-size: 13px;
  font-weight: 700;
  color: var(--demo-fg);
  padding-bottom: 8px;
  text-shadow: 0 1px 3px rgba(0,0,0,0.5);
}

.vat-bubbles {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.particle {
  position: absolute;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  opacity: 0;
  animation: floatUp 1.4s ease-in-out infinite;
}

@keyframes floatUp {
  0% {
    transform: translateY(100px) scale(0.5);
    opacity: 0;
  }
  50% {
    opacity: 0.9;
  }
  100% {
    transform: translateY(0px) scale(1.2);
    opacity: 0;
  }
}

demo.js:
document.addEventListener('DOMContentLoaded', () => {
  const samplesList = document.getElementById('samples-list');
  const atmosInput = document.getElementById('atmos-input');
  const analyzeBtn = document.getElementById('analyze-btn');
  const statusEl = document.getElementById('status-el');
  const celestialOrb = document.getElementById('celestial-orb');
  const skyBarFill = document.getElementById('sky-bar-fill');
  const skyVal = document.getElementById('sky-val');

  const categories = ['neon_synthwave', 'earthy_acoustic', 'pastel_lofi', 'golden_sunset'];

  // Render Sample Chips
  if (window.TypeSafeDemo && Array.isArray(window.TypeSafeDemo.samples)) {
    window.TypeSafeDemo.samples.forEach((sample, idx) => {
      const chip = document.createElement('button');
      chip.className = 'sample-chip';
      chip.textContent = sample.description || `Sample ${idx + 1}`;
      chip.addEventListener('click', () => {
        const text = typeof sample.state === 'string' 
          ? sample.state 
          : (sample.state && sample.state.playlist_description) || '';
        atmosInput.value = text;
        triggerEvaluation();
      });
      samplesList.appendChild(chip);
    });
  }

  // Theme Handler
  if (window.TypeSafeDemo && typeof window.TypeSafeDemo.onTheme === 'function') {
    window.TypeSafeDemo.onTheme((theme) => {
      const demoEl = document.getElementById('demo');
      if (demoEl) demoEl.setAttribute('data-theme', theme);
    });
  }

  atmosInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      triggerEvaluation();
    }
  });

  analyzeBtn.addEventListener('click', () => {
    triggerEvaluation();
  });

  function triggerEvaluation() {
    const text = atmosInput.value.trim();
    if (!text) {
      statusEl.textContent = 'Please enter a playlist atmosphere description.';
      statusEl.className = 'status-box error';
      return;
    }

    analyzeBtn.disabled = true;
    statusEl.textContent = 'Analyzing atmosphere and calculating color archetype vectors...';
    statusEl.className = 'status-box loading';

    const state = { playlist_description: text };

    window.TypeSafeDemo.evaluate(state)
      .then((answers) => {
        analyzeBtn.disabled = false;
        statusEl.className = 'status-box';
        statusEl.textContent = 'Atmosphere mapped successfully.';
        updateVisuals(answers);
      })
      .catch((err) => {
        analyzeBtn.disabled = false;
        statusEl.className = 'status-box error';
        const msg = window.TypeSafeDemo && window.TypeSafeDemo.describeError
          ? window.TypeSafeDemo.describeError(err)
          : 'Failed to analyze text.';
        statusEl.textContent = msg;
      });
  }

  function updateVisuals(answers) {
    // 1. Handle Nighttime (Noul)
    const nightAnswer = answers.is_nighttime;
    let noulVal = 0;
    if (nightAnswer && typeof nightAnswer.noul === 'number') {
      noulVal = nightAnswer.noul;
    }
    const nightPct = Math.round(noulVal * 100);
    skyBarFill.style.width = `${nightPct}%`;
    skyVal.textContent = noulVal >= 0.5 ? `Nighttime (${nightPct}%)` : `Daylight (${100 - nightPct}%)`;

    // Celestial orb shift: Sun at top (0px), Moon at bottom (-32px)
    if (noulVal >= 0.5) {
      celestialOrb.style.transform = 'translateY(-32px)';
    } else {
      celestialOrb.style.transform = 'translateY(0px)';
    }

    // 2. Handle Palette Category (Choice & Probabilities)
    const catAnswer = answers.palette_category;
    const probs = (catAnswer && catAnswer.probabilities) || {};
    const topChoice = catAnswer ? catAnswer.choice : null;

    categories.forEach((cat) => {
      const p = typeof probs[cat] === 'number' ? probs[cat] : (topChoice === cat ? 1 : 0);
      const pct = Math.round(p * 100);

      const liquid = document.getElementById(`liquid-${cat}`);
      const pctLabel = document.getElementById(`pct-${cat}`);
      const card = document.querySelector(`.vat-card[data-category="${cat}"]`);
      const bubbleContainer = document.getElementById(`bubbles-${cat}`);

      if (liquid) liquid.style.height = `${pct}%`;
      if (pctLabel) pctLabel.textContent = `${pct}%`;

      if (card) {
        if (topChoice === cat) {
          card.classList.add('active-archetype');
        } else {
          card.classList.remove('active-archetype');
        }
      }

      // Trigger particles for matching liquid containers
      if (bubbleContainer) {
        bubbleContainer.innerHTML = '';
        if (pct > 15) {
          const particleCount = Math.min(8, Math.floor(pct / 12));
          for (let i = 0; i < particleCount; i++) {
            const particle = document.createElement('div');
            particle.className = 'particle';
            particle.style.left = `${10 + Math.random() * 80}%`;
            particle.style.animationDelay = `${Math.random() * 1.2}s`;
            particle.style.background = getParticleColor(cat);
            bubbleContainer.appendChild(particle);
          }
        }
      }
    });
  }

  function getParticleColor(category) {
    switch (category) {
      case 'neon_synthwave': return '#00f2fe';
      case 'earthy_acoustic': return '#a8e063';
      case 'pastel_lofi': return '#ffb6c1';
      case 'golden_sunset': return '#ff7e5f';
      default: return '#ffffff';
    }
  }
});
